"use client";
import { useUser } from "centralauth/client";

export default function Home() {
  const { user } = useUser();
  const authError =
    typeof window !== "undefined"
      ? new URLSearchParams(window.location.search).get("auth_error")
      : null;

  return (
    <div className="min-h-screen flex flex-col justify-center items-center gap-8 p-8 font-[family-name:var(--font-geist-sans)]">
      {authError && (
        <p className="text-red-600" role="alert">Authentication failed: {authError}</p>
      )}
      {!!user && (
        <>
          <p>{`You are logged in as ${user.email}.`}</p>
          <a
            className="rounded-full border border-solid border-gray-600 px-8 py-2"
            href="/api/auth/logout"
          >
            Log out
          </a>
        </>
      )}
      {user === null && (
        <a
          className="rounded-full border border-solid border-gray-600 px-8 py-2"
          href="/api/auth/login"
        >
          Log in
        </a>
      )}
    </div>
  );
}
